parameters.jsonBody:
={"model": "llama-3.3-70b-versatile", "temperature": 0.3, "max_tokens": 1024, "messages": [{"role": "system", "content": "You are a scheduling assistant. Extract meeting details from natural language requests."}, {"role": "user", "content": "Extract: meeting_title, participants (array of names/emails), preferred_date (ISO 8601 datetime), duration_minutes (number), agenda.

Request:
{{ $json.body.request_text }}

Respond with ONLY valid JSON: {"fields":{"meeting_title":"","participants":[],"preferred_date":"","duration_minutes":60,"agenda":""}}"}]}

parameters.jsCode:
const raw = $input.item.json?.choices?.[0]?.message?.content || '{"fields":{}}';
let fields = {};
try { const m = raw.match(/\{[\s\S]*\}/); if(m) fields = JSON.parse(m[0]).fields || {}; } catch(e) {}
const webhook = $('Webhook -- Schedule Request').item.json;
return [{ json: { fields, requester_email: webhook.body?.requester_email || '' } }];

parameters.message:
=Your meeting '{{ $json.fields.meeting_title }}' has been scheduled.

Date/Time: {{ $json.fields.preferred_date }}
Duration: {{ $json.fields.duration_minutes }} minutes
Participants: {{ $json.fields.participants }}
Agenda: {{ $json.fields.agenda }}

Calendar invites will be sent to all participants.
